"""Revision two: user/environment identity model and disposable sessions."""
import re


def revise(page):
    page = page.replace('A browser for every role', 'Users, environments and temporary sessions')
    page = page.replace('CONCEPT 01', 'CONCEPT 03')
    page = page.replace('Every side of the story.', 'Every user. Every environment.')
    page = page.replace('Keep Owner, Driver, and Intaker signed in side by side—like separate desks in one control room, each with its own keys.', 'Keep seven or more users side by side, with separate email/password logins for Local, QA and Production—like one control room with a different set of keys for each site.')
    page = page.replace('Your app, from every role.', 'Users first. Roles are optional labels.')
    page = page.replace('Try the layout presets and account selectors.', 'Switch environments, view accounts, or create a temporary copy.')
    page = page.replace('Owner pane → Owner session', 'Jordan → QA account → session').replace('Driver pane → Driver session', 'Alex → QA account → session').replace('Intaker pane → Intaker session', 'Sam → QA account → session')
    page = page.replace('Uses its own repo tools', 'Operates pages + sees images')
    page = page.replace('<span class="env">LOCAL DEVELOPMENT</span>', '<label class="env">ENVIRONMENT <select id="environment" aria-label="Workspace environment"><option value="local">Local</option><option value="qa" selected>QA</option><option value="production">Production</option></select></label>')
    page = re.sub(r'<aside class="sidebar">.*?</aside>', '''<aside class="sidebar"><div class="workspace">▧ Dispatch<small id="base-url">https://qa.dispatch.example</small></div><h3>USERS · OPTIONAL ROLE LABELS</h3><div id="user-list"></div><button id="add">＋ Add user</button><div class="side-bottom"><button id="vault">◇ Users &amp; credentials</button><p>Separate accounts per environment.<br>Temporary copies clean up after use.</p><button id="agent">⌘ Agent connection</button></div></aside>''', page, flags=re.S)
    page = page.replace('<button data-layout="grid" aria-pressed="true">▦ Four-way</button>', '<button data-layout="all" aria-pressed="true">▦ All users</button><button data-layout="grid" aria-pressed="false">▦ Four-way</button>')
    page = page.replace('class="panes" data-layout="grid"', 'class="panes" data-layout="all"')
    page = page.replace('Code edits stay with your coding agent.', 'Agents operate the website and receive screenshots as images. No code-editing tools are included.')
    page = page.replace('Each account and environment gets a persistent Chromium session. Two panes using the same profile share its login. Separate profiles keep separate logins.', 'A User has an optional role and separate account entries for Local, QA and Production. An extra pane shares a session; a temporary copy creates a fresh one using the same saved login configuration.')
    page = page.replace('Profile ≠ pane', 'User → account → session')
    page = page.replace('project / environment / accountId', 'user / environment / account / instance')
    page = page.replace('horizontal(60%, Owner,<br>vertical(50%, Driver, Intaker))', '7+ panes · nested splits · focus mode<br>No four-user or four-pane ceiling')
    page = page.replace('Some OAuth providers block embedded browsers. MFA and passkeys can require a person. Prove your actual login before promising automatic sign-in.', 'Email/password is the main flow. Configure each environment’s login URL and fields, then check the signed-in identity. MFA, if present, can pause for a person.')
    page = page.replace('Embedded authentication needs an early test.', 'Login targets a user, account and environment.')
    page = re.sub(r'<pre>roles profiles create.*?</pre>', '''<pre>roles users create --id alex --role driver
roles accounts add --user alex --env qa
  --id alex-qa --secret-ref vault:alex-qa

roles panes open --user alex --env qa
roles users copy --user alex --temporary
roles capture --pane pane-7 --format png
roles temporary delete --id copy-1
roles mcp serve</pre>''', page, flags=re.S)
    start = page.index('<section class="section" id="questions">')
    end = page.index('<footer>', start)
    page = page[:start] + '''<section class="section" id="questions"><div class="eyebrow">06 / Decisions captured</div><h2>Your answers are now the design.</h2><p class="note">No need to answer the earlier questionnaire again. These explain the updated behavior.</p><details open><summary>How do Users, roles and environments fit together?</summary><p>A <strong>User</strong> is the saved testing identity. Its role is an optional label. Each environment has its own URL, email/password entries and browser sessions. A user can have multiple account entries in the same environment.</p><p><strong>Why:</strong> you can test two Drivers, seven different roles, or an app without roles using the same model.</p></details><details><summary>What does a temporary copy inherit?</summary><p>Its source user’s settings and access to saved credentials. It gets a fresh isolated browser session and can use the same account or another saved entry. Temporary credential changes do not modify the source.</p><p><strong>Why:</strong> this gives you disposable testing space without repeatedly typing credentials. Same credentials still identify the same backend account.</p></details><details><summary>What gets deleted with the temporary copy?</summary><p>Its sessions, cookies/cache/storage, app-managed temporary captures, copy-owned credential overrides and local metadata. The source user and shared credential entries remain. Explicitly exported files and backend records remain.</p><p><strong>Why:</strong> cleanup should reclaim the copy’s resources without deleting the account you copied from. An in-memory session avoids a lasting browser-profile folder.</p></details><details><summary>Can agents see and operate the website?</summary><p>Yes: click, type, navigate, log in, inspect and capture. MCP returns screenshot image content to vision-capable agents, not only a local path. Pane identity and environment accompany each capture.</p><p><strong>Why:</strong> external agents can use both screenshots and structured page information. This browser does not need source-editing tools.</p></details><details open><summary>What did “looking right is not the same as working” mean?</summary><p>Example: a Driver clicks <strong>Accept job</strong>. A screenshot can show the button changed. The agent should also check that the Owner sees the job as <strong>Accepted</strong>.</p><p><strong>Why:</strong> this catches a screen that updates without saving the change. It was an explanation, not another decision or question for you.</p></details><details><summary>Which details will implementation need?</summary><p>Your real Local, QA and Production URLs and the login form structure. Email/password is already selected as the main login method. The optional split diagram can refine the default layout.</p><p><strong>Why:</strong> these connect the generic browser design to your actual application; they do not block this mockup.</p></details></section>''' + page[end:]
    page = page.replace('Layouts, profile selectors, focus-width slider, dialogs, and scenario steps are mock interactions.', 'Seven-user layouts, environment/account selection, temporary-copy creation/deletion, dialogs and scenario steps are mock interactions.')
    css = '''
.hero h1{font-size:clamp(35px,4vw,60px)}.shell{grid-template-columns:205px minmax(0,1fr)}.env select{background:#354b39;color:var(--green);border:0;font-size:11px}.profile{padding:5px;font-size:11px;width:100%;text-align:left;border:0;background:transparent}.profile small{font-size:9px}.sidebar .side-bottom{padding-top:18px}.workspace small{overflow-wrap:anywhere}.panes[data-layout=all]{grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:none;grid-auto-rows:300px}.panes[data-layout=grid] .pane:nth-child(n+5),.panes[data-layout=wide] .pane:nth-child(n+4){display:none}.panes[data-layout=all] .pane{display:flex}.pane-head{flex-wrap:wrap;justify-content:start}.pane-head select{width:105px}.pane-head .account-select{width:75px}.pane-actions{display:flex;gap:4px;flex-wrap:wrap;background:#242e37;padding:4px 6px}.pane-actions button{font-size:9px;padding:2px 5px}.temp{border-style:dashed}.temp-label{color:#e9c18d;font-size:9px;margin-left:auto}.pane-foot{gap:6px}.page h3{font-size:17px}.page{padding:11px}.metrics{gap:4px}.metric{padding:5px}.metric strong{font-size:18px}.account-table{border-collapse:collapse;width:100%;font-size:11px}.account-table th,.account-table td{text-align:left;padding:10px 7px;border-bottom:1px solid #4c5a47}.account-table small{display:block;color:#a4b49a}.account-table code{font-size:10px;overflow-wrap:anywhere}dialog{max-width:720px;max-height:85vh;overflow:auto}.dialog-tabs{display:flex;gap:5px;margin:12px 0}.dialog-tabs button{font-size:12px}.environment-note{color:var(--muted);font-size:10px;padding:5px 13px;border-bottom:1px solid var(--line)}@media(max-width:1100px){.panes[data-layout=all]{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:740px){.shell{grid-template-columns:1fr}.panes[data-layout=all]{grid-template-columns:1fr}.panes[data-layout=all]{grid-auto-rows:330px}.chrome{flex-wrap:wrap}.account-table{font-size:10px}}
'''
    page = page.replace('</style>', css + '</style>')
    old_script = page[page.index('<script>') + len('<script>'):page.index('</script>')]
    content_fn = old_script[old_script.index('function content('):old_script.index('function render(')]
    content_fn = content_fn.replace("return '<div class=\"denied\">", "if(role!=='guest')return '<h3>'+role.charAt(0).toUpperCase()+role.slice(1)+' workspace</h3><p>Illustrative account-specific view.</p><div class=\"job\"><div>JOB-1042 · Riverside pickup<small>Shared record · independently signed in</small></div><span class=\"status\">Demo</span></div>';return '<div class=\"denied\">")
    page = page.replace('<section class="section" id="plan">', '''<section class="section" id="credential-tools"><div class="eyebrow">Agent credentials / write and use, never read back</div><h2>Create an account. Save its login. Keep it private.</h2><div class="cards"><article class="card"><div class="eyebrow">Write</div><h3>Save or replace</h3><p>An agent can store an email/password pair for a specific User, account and environment. Overwrite requires the current revision. Neither operation returns credential values.</p><code>credentials_put → reference + revision</code></article><article class="card"><div class="eyebrow">Use</div><h3>Login by reference</h3><p>The browser fills the approved login page privately. The agent gets the outcome, not the password. The same contract applies in Local, QA and Production.</p><code>auth_login(credentialRef, paneId)</code></article><article class="card"><div class="eyebrow">Optional generation</div><h3>Keep it out of model context</h3><p>The browser can generate the password and use it through an approved registration recipe. If an agent supplies a password itself, it already knows that value.</p><code>credentials_generate → opaque reference</code></article></div><p class="note">No read, reveal or export tools. Protected login operations block indirect inspection of filled credentials. External agent logs may retain values the agent supplied; write-only storage cannot erase that history. Updating the vault does not change the website’s password.</p><button id="credential-demo">Preview write-only tool response</button></section><section class="section" id="plan">''')
    page = page.replace('<details><summary>Can agents see and operate the website?</summary>', '''<details open><summary>Can an agent save credentials for an account it created?</summary><p><strong>Yes.</strong> It can create or overwrite the stored email/password pair and use the resulting reference to log in. It cannot retrieve either value from the vault. Status responses contain only IDs, configured state, revision and verification state.</p><p><strong>Why:</strong> test accounts can be created automatically and reused later without exposing stored logins to later agents. An agent still knows any password it originally supplied; browser-generated passwords avoid that exposure.</p></details><details><summary>Can agents see and operate the website?</summary>''')
    script = SCRIPT.replace('__CONTENT__', content_fn)
    script = script.replace('The desktop editor will support Add account, email/password editing and login recipes.', 'The desktop editor supports account credentials and login recipes. Agents can save or overwrite the stored pair through credentials_put, but cannot read it back; they receive a credential reference and revision only.')
    script += r'''
let credentialDemoRevision=0;
document.getElementById('credential-demo').onclick=()=>{credentialDemoRevision++;modal('Write-only credential receipt · demo','<p>Simulated '+(credentialDemoRevision===1?'create':'replace')+' for Alex / QA. No actual credentials are submitted or stored.</p><pre>'+JSON.stringify({credentialRef:'cred_demo_123',configured:true,revision:credentialDemoRevision,verification:'unverified'},null,2)+'</pre><p>No email, password, previous value or masked fragments are returned. Login uses the reference internally.</p><p>Close and click again to preview a replacement receipt. Updating this entry would not change the website account’s password.</p>')};
'''
    page = re.sub(r'<script>.*?</script>', lambda _: '<script>' + script + '</script>', page, flags=re.S)
    return page


SCRIPT = r'''
const users={jordan:{name:'Jordan',role:'Owner',kind:'owner',route:'/overview'},alex:{name:'Alex',role:'Driver',kind:'driver',route:'/my-jobs'},sam:{name:'Sam',role:'Intaker',kind:'intaker',route:'/intake'},casey:{name:'Casey',role:'Dispatcher',kind:'dispatcher',route:'/dispatch'},morgan:{name:'Morgan',role:'Billing',kind:'billing',route:'/billing'},riley:{name:'Riley',role:'Manager',kind:'manager',route:'/reports'},jamie:{name:'Jamie',role:'',kind:'member',route:'/home'}};
const environments={local:{name:'Local',url:'http://localhost:3000'},qa:{name:'QA',url:'https://qa.dispatch.example'},production:{name:'Production',url:'https://dispatch.example'}};
let environment='qa',step=0,nextId=8,timer;
let bindings=Object.keys(users).map((user,i)=>({id:'pane-'+(i+1),user,session:'session-'+(i+1),temporary:false,accounts:{}}));
const panes=document.getElementById('panes');
function accounts(user,env){return user==='alex'?['Alex','Taylor']:env==='production'&&user==='jamie'?[]:[users[user].name]}
function selectedAccount(b){const options=accounts(b.user,environment);return options[b.accounts[environment]||0]||null}
function color(u){return ['owner','driver','intaker'].includes(u.kind)?u.kind:'guest'}
__CONTENT__
function render(){
document.getElementById('base-url').textContent=environments[environment].url;
document.getElementById('user-list').innerHTML=Object.entries(users).map(([id,u])=>'<button class="profile" data-user-info="'+id+'" style="--role:var(--'+color(u)+')"><span class="avatar">'+u.name[0]+'</span><span>'+u.name+'<small>'+(u.role||'No role label')+' · '+accounts(id,environment).length+' account(s)</small></span></button>').join('');
panes.innerHTML=bindings.map(b=>{const u=users[b.user],a=selectedAccount(b),opts=accounts(b.user,environment);return '<article class="pane '+(b.temporary?'temp':'')+'" style="--role:var(--'+color(u)+')"><div class="pane-head"><select aria-label="User for '+b.id+'" data-user-pane="'+b.id+'">'+Object.entries(users).map(([id,v])=>'<option value="'+id+'" '+(id===b.user?'selected':'')+'>'+v.name+(v.role?' · '+v.role:'')+'</option>').join('')+'</select><select class="account-select" aria-label="Account for '+b.id+'" data-account-pane="'+b.id+'">'+(opts.length?opts.map((n,i)=>'<option value="'+i+'" '+((b.accounts[environment]||0)===i?'selected':'')+'>'+n+'</option>').join(''):'<option>Not configured</option>')+'</select>'+(b.temporary?'<span class="temp-label">TEMP</span>':'')+'</div><div class="url">'+environments[environment].name+' · '+environments[environment].url+u.route+'</div><div class="pane-actions"><button data-info="'+b.user+'">Accounts</button><button data-copy="'+b.id+'">Temporary copy</button><button data-extra="'+b.id+'">Extra pane</button><button data-shot="'+b.id+'">Screenshot</button>'+(b.temporary?'<button data-delete="'+b.id+'">Delete copy</button>':'')+'</div><div class="page"><div class="app-brand"><b>↗ DISPATCH</b><span>'+(a||'No login')+(u.role?' · '+u.role:'')+'</span></div>'+(a?content(u.kind).replace('Good morning, Alex.','Good morning, '+a+'.'):'<h3>Not configured</h3><p>Add a Production account for Jamie. No QA or Local credentials will be reused.</p>')+'</div><div class="pane-foot"><span>'+b.id+' · '+b.session+'</span><span>'+(b.temporary?'Disposable':'Saved')+' · '+environments[environment].name+'</span></div></article>'}).join('');
}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('show'),4800)}
function modal(title,body){document.getElementById('modal-title').textContent=title;document.getElementById('modal-body').innerHTML=body;document.getElementById('modal').showModal()}
document.getElementById('close').onclick=()=>document.getElementById('modal').close();
function showAccounts(id,env=environment,open=true){const u=users[id],e=environments[env];const rows=accounts(id,env);document.getElementById('modal-title').textContent=u.name+' · '+(u.role||'No role label');document.getElementById('modal-body').innerHTML='<p>Email/password accounts are stored separately for each environment. Role is optional. These are fictional read-only examples.</p><div class="dialog-tabs">'+Object.entries(environments).map(([key,value])=>'<button data-credential-env="'+key+'" data-info-user="'+id+'" aria-pressed="'+(key===env)+'">'+value.name+'</button>').join('')+'</div><p><code>'+e.url+'</code><br>Login path: <code>/login</code> · example configuration</p><table class="account-table"><thead><tr><th>Account</th><th>Email</th><th>Password</th></tr></thead><tbody>'+rows.map(n=>'<tr><td>'+n+'</td><td>'+n.toLowerCase()+'.'+env+'@example.com</td><td>••••••••<small>Saved locally in the real app</small></td></tr>').join('')+'</tbody></table>'+(rows.length?'':'<p>No account configured. Another environment’s credentials are never reused.</p>')+'<p>The desktop editor will support Add account, email/password editing and login recipes. Temporary copies inherit these references; overrides belong only to the copy. This public page does not accept or store credentials.</p>';if(open)document.getElementById('modal').showModal()}
document.getElementById('modal-body').onclick=e=>{let b=e.target.closest('[data-credential-env]');if(b)showAccounts(b.dataset.infoUser,b.dataset.credentialEnv,false)};
document.getElementById('user-list').onclick=e=>{let b=e.target.closest('[data-user-info]');if(b)showAccounts(b.dataset.userInfo)};
document.getElementById('environment').onchange=e=>{environment=e.target.value;render();toast('Demo environment switched: matching accounts + URL. Missing accounts remain unconfigured.');};
document.querySelectorAll('button[data-layout]').forEach(b=>b.onclick=()=>{panes.dataset.layout=b.dataset.layout;document.querySelectorAll('button[data-layout]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));toast(b.dataset.layout==='all'?'All '+bindings.length+' panes shown. No four-pane ceiling.':'Focus preset: other user sessions remain available in All users.')});
document.getElementById('ratio').oninput=e=>{panes.style.setProperty('--ratio',e.target.value+'%');if(panes.dataset.layout!=='wide')document.querySelector('button[data-layout="wide"]').click()};
panes.onchange=e=>{const el=e.target;if(el.dataset.userPane){const b=bindings.find(x=>x.id===el.dataset.userPane);b.user=el.value;b.accounts={};b.session='session-'+nextId++;render();toast('Pane rebound to the selected user in this demo.')}if(el.dataset.accountPane){const b=bindings.find(x=>x.id===el.dataset.accountPane);b.accounts[environment]=Number(el.value);b.session='session-'+nextId++;render();toast('Selected a separate account entry for this environment.')}};
function capture(pane){modal('Screenshot for agent vision','<p>Target: <strong>'+pane+'</strong> · '+environments[environment].name+'</p><p>The real MCP tool returns PNG image content plus user, account, URL, viewport dimensions, capture ID and time. A vision-capable agent receives the actual image, not just a file path.</p><p>Also support all-pane captures and a workspace composite. Coordinate clicks use viewport-relative CSS pixels and a current capture ID; structured DOM snapshots remain available.</p><p>No real screenshot was captured by this mockup.</p>')}
panes.onclick=e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.info){showAccounts(el.dataset.info);return}if(el.dataset.shot){capture(el.dataset.shot);return}if(el.dataset.copy||el.dataset.extra){const b=bindings.find(x=>x.id===(el.dataset.copy||el.dataset.extra));const n=nextId++;const copy=Boolean(el.dataset.copy);bindings.push({...b,id:'pane-'+n,session:copy?'temp-'+n:b.session,temporary:copy||b.temporary,accounts:{...b.accounts}});render();document.querySelector('button[data-layout="all"]').click();toast(copy?'Temporary copy created in demo: inherited credential references, new isolated session.':'Extra pane opened in demo: same account and session.');return}if(el.dataset.delete){const b=bindings.find(x=>x.id===el.dataset.delete);bindings=bindings.filter(x=>x.session!==b.session);render();toast('Demo copy removed. Real cleanup removes its temporary storage and owned artifacts; source user and credentials remain.');return}if(el.dataset.action==='accept')setStep(2);if(el.dataset.action==='create')setStep(0)};
const steps=[['Sam creates the job.','The agent uses Sam’s Intaker account in the chosen environment and captures the real job ID.','Check: the new job appears.'],['Jordan assigns Alex.','The agent uses Jordan’s Owner account to find that job and assign Alex.','Check: Alex sees the assigned job.'],['Alex accepts the assignment.','The agent opens Alex’s account, accepts the job and takes a screenshot.','Check: acceptance is saved.'],['Jordan sees Accepted.','The agent returns to Jordan’s account and verifies the new job status.','The earlier question meant this: check the result as well as the screenshot.']];
function setStep(n){step=n;const s=steps[n];document.getElementById('walk').innerHTML='<h3>'+s[0]+'</h3><p>'+s[1]+'</p><p style="color:var(--green)">'+s[2]+'</p>';document.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.step)===n)));document.getElementById('run-title').textContent='Demo step '+(n+1)+'/4: '+s[0];render()}
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>setStep(Number(b.dataset.step)));document.getElementById('run').onclick=()=>setStep((step+1)%4);
document.getElementById('capture').onclick=()=>capture('all open panes');
document.getElementById('vault').onclick=()=>showAccounts('alex');
document.getElementById('add').onclick=()=>modal('Add user · desktop form concept','<p><strong>Display name:</strong> Delivery tester<br><strong>Role label:</strong> Driver (optional)</p><p>Environment tabs: Local / QA / Production. Each contains its URL and any number of account entries with label, email and password.</p><p>A User does not require a role and can group more than one account. Add real credentials in the desktop editor, not this public demo.</p>');
document.getElementById('agent').onclick=()=>modal('Agents operate the website','<p>Connect an external agent through MCP or CLI. Tools: navigate, log in, click, type, inspect, wait, screenshot, temporary copy and cleanup.</p><p>Screenshot tools return image content for vision-capable agents. Every action identifies the pane, user/account and environment. Pending actions stop if the pane changes environment.</p><p>No repository-editing tool is included. No agent is connected to this demo.</p>');
setStep(0);
'''
